def inr_format(number):
    str_num = str(number)
    if len(str_num) <= 3:
        return str_num + ',0' * (3 - len(str_num))
    else:
        formatted = str_num[-3:]
        for i in range(len(str_num) - 3)[::-1]:
            formatted = str_num[i:i+2] + ',' + formatted
        return formatted

def inr_format(n):
    if n < 0:
        raise ValueError("Negative numbers are not supported")
    s = str(n)
    if len(s) <= 3:
        return s
    else:
        return s[:-3] + ',' + s[-3:][::-1]

